#!/usr/bin/env bash
# The Homebrew formula for a release (ADR 0043), from its SHA256SUMS:
#   scripts/homebrew-formula.sh 0.12.0 dist/SHA256SUMS > Formula/bimble.rb
set -euo pipefail
v="$1"; sums="$2"
url="https://github.com/guilbep/bimble/releases/download/v$v"
sha() {
  local f="bimble-$v-$1.tar.gz" s
  s=$(awk -v f="$f" '$2 == f || $2 == "*"f {print $1}' "$sums")
  [[ -n "$s" ]] || { echo "no checksum for $f in $sums" >&2; exit 1; }
  echo "$s"
}
cat <<RUBY
# Generated by scripts/homebrew-formula.sh from the release's SHA256SUMS (ADR 0043).
class Bimble < Formula
  desc "Open-source structural BIM: view IFC, draw plans, edit and version models"
  homepage "https://github.com/guilbep/bimble"
  version "$v"
  license "MIT"

  on_macos do
    on_arm do
      url "$url/bimble-$v-aarch64-apple-darwin.tar.gz"
      sha256 "$(sha aarch64-apple-darwin)"
    end
    on_intel do
      url "$url/bimble-$v-x86_64-apple-darwin.tar.gz"
      sha256 "$(sha x86_64-apple-darwin)"
    end
  end

  on_linux do
    on_intel do
      url "$url/bimble-$v-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "$(sha x86_64-unknown-linux-gnu)"
    end
  end

  def install
    bin.install "bimble"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/bimble --version")
  end
end
RUBY
